use crate::common;
use rust_xlsxwriter::{
    ConditionalFormatCustomIcon, ConditionalFormatIconSet, ConditionalFormatIconType,
    ConditionalFormatType, Workbook, XlsxError,
};

// Test an Excel 2010 extension icon set conditional format.
fn create_new_xlsx_file_1(filename: &str) -> Result<(), XlsxError> {
    let mut workbook = Workbook::new();

    let worksheet = workbook.add_worksheet();

    for row in 0..5 {
        worksheet.write(row, 0, row + 1)?;
    }

    // The ThreeTriangles icon set is only available in Excel 2010 and later.
    let conditional_format =
        ConditionalFormatIconSet::new().set_icon_type(ConditionalFormatIconType::ThreeTriangles);

    worksheet.add_conditional_format(0, 0, 4, 0, &conditional_format)?;

    workbook.save(filename)?;

    Ok(())
}

// Check that "Stop If True" is ignored for icon sets, since Excel doesn't
// allow it to be set for them.
fn create_new_xlsx_file_2(filename: &str) -> Result<(), XlsxError> {
    let mut workbook = Workbook::new();

    let worksheet = workbook.add_worksheet();

    for row in 0..5 {
        worksheet.write(row, 0, row + 1)?;
    }

    let conditional_format = ConditionalFormatIconSet::new()
        .set_icon_type(ConditionalFormatIconType::ThreeTriangles)
        .set_stop_if_true(true);

    worksheet.add_conditional_format(0, 0, 4, 0, &conditional_format)?;

    workbook.save(filename)?;

    Ok(())
}

// Check that Lowest and Automatic icon rules are written as percent rules.
fn create_new_xlsx_file_3(filename: &str) -> Result<(), XlsxError> {
    let mut workbook = Workbook::new();

    let worksheet = workbook.add_worksheet();

    for row in 0..5 {
        worksheet.write(row, 0, row + 1)?;
    }

    let icons = [
        ConditionalFormatCustomIcon::new(),
        ConditionalFormatCustomIcon::new().set_rule(ConditionalFormatType::Lowest, 33),
        ConditionalFormatCustomIcon::new().set_rule(ConditionalFormatType::Automatic, 67),
    ];

    let conditional_format = ConditionalFormatIconSet::new()
        .set_icon_type(ConditionalFormatIconType::ThreeTriangles)
        .set_icons(&icons);

    worksheet.add_conditional_format(0, 0, 4, 0, &conditional_format)?;

    workbook.save(filename)?;

    Ok(())
}

#[test]
fn test_cond_format27() {
    let test_runner = common::TestRunner::new()
        .set_name("cond_format27")
        .set_function(create_new_xlsx_file_1)
        .unique("1")
        .initialize();

    test_runner.assert_eq();
    test_runner.cleanup();
}

#[test]
fn test_cond_format27_stop_if_true() {
    let test_runner = common::TestRunner::new()
        .set_name("cond_format27")
        .set_function(create_new_xlsx_file_2)
        .unique("2")
        .initialize();

    test_runner.assert_eq();
    test_runner.cleanup();
}

#[test]
fn test_cond_format27_lowest_automatic() {
    let test_runner = common::TestRunner::new()
        .set_name("cond_format27")
        .set_function(create_new_xlsx_file_3)
        .unique("3")
        .initialize();

    test_runner.assert_eq();
    test_runner.cleanup();
}
